// ─── File: InheritableThreadLocalDemo.java ───
// Runnable demo. In a real project each class lives in its own file.
package com.bank.tracing;

import java.util.concurrent.*;
import java.util.logging.*;

public class InheritableThreadLocalDemo {
    private static final Logger LOG = Logger.getLogger("Tracing");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        LOG.setUseParentHandlers(false);
        LOG.addHandler(h);
        LOG.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        // Pool is built by the bootstrap thread whose correlation id is SYSTEM-INIT.
        RequestContext.set("SYSTEM-INIT");
        ExecutorService rawPool = Executors.newFixedThreadPool(2);

        // --- WRONG: directly spawned thread inherits correctly, pool does NOT ---
        RequestContext.set("REQ-RAJESH-001");           // this request's id
        Thread direct = new Thread(() ->
            LOG.info(() -> "direct child sees: " + RequestContext.get()));   // REQ-RAJESH-001 ✓
        direct.start(); direct.join();

        rawPool.submit(() ->
            LOG.warning(() -> "pool worker sees (STALE): " + RequestContext.get())).get();  // SYSTEM-INIT ✗

        // --- RIGHT: explicit propagation per task via wrapper ---
        ContextPropagatingExecutor safePool = new ContextPropagatingExecutor(rawPool);
        RequestContext.set("REQ-RAJESH-001");
        safePool.submit(() -> LOG.info(() -> "safe worker (Rajesh): " + RequestContext.get())).get();
        RequestContext.set("REQ-PRIYA-002");
        safePool.submit(() -> LOG.info(() -> "safe worker (Priya): " + RequestContext.get())).get();

        rawPool.shutdown();
    }
}

// ─── Would be in context/RequestContext.java ───
class RequestContext {
    // Inheritable so a directly spawned child gets the parent's value automatically.
    private static final InheritableThreadLocal<String> CORRELATION = new InheritableThreadLocal<>();
    static void set(String id) { CORRELATION.set(id); }
    static String get() { return CORRELATION.get(); }
    static void clear() { CORRELATION.remove(); }       // MUST clear on pooled threads
}

// ─── Would be in executor/ContextPropagatingExecutor.java ───
class ContextPropagatingExecutor {
    private final ExecutorService delegate;
    ContextPropagatingExecutor(ExecutorService delegate) { this.delegate = delegate; }

    Future<?> submit(Runnable task) {
        String captured = RequestContext.get();          // capture on SUBMITTING thread
        return delegate.submit(() -> {
            RequestContext.set(captured);                 // set explicitly on the WORKER
            try { task.run(); }
            finally { RequestContext.clear(); }           // clear to prevent leakage to next task
        });
    }
}
```

