// ─── File: src/test/java/com/bank/tracing/context/RequestContextTest.java ───
package com.bank.tracing.context;

import com.bank.tracing.executor.ContextPropagatingExecutor;
import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;

class RequestContextTest {
    @Test
    void explicitPropagationGivesEachTaskItsOwnId() throws Exception {
        ExecutorService raw = Executors.newFixedThreadPool(1);
        ContextPropagatingExecutor safe = new ContextPropagatingExecutor(raw);
        RequestContext.set("REQ-A");
        String a = extract(safe);
        RequestContext.set("REQ-B");
        String b = extract(safe);
        assertEquals("REQ-A", a);
        assertEquals("REQ-B", b);   // reused worker did NOT leak REQ-A into REQ-B
        raw.shutdown();
    }
    private String extract(ContextPropagatingExecutor safe) throws Exception {
        var ref = new java.util.concurrent.atomic.AtomicReference<String>();
        safe.submit(() -> ref.set(RequestContext.get())).get();
        return ref.get();
    }
}
```
